package com.yourapp.drama.production;
import java.util.*;
/** Selects verbatim task-relevant Markdown sections so provider rules fit the final prompt budget. */
public final class ProviderRulePackProjector {
 public String project(String markdown,VideoTaskType task,int maxChars){if(markdown==null||markdown.isBlank()||markdown.length()<=maxChars)return markdown==null?"":markdown;String[] blocks=markdown.split("(?m)(?=^#{1,4}\\s)");List<String> keywords=new ArrayList<>(List.of("限制","必须","禁止","参考","素材","参数","镜头","时长","比例","运镜","主体"));keywords.addAll(switch(task){case FIRST_FRAME_GENERATE,KEYFRAME_GENERATE->List.of("首帧","图生视频","单图");case FIRST_LAST_FRAME_GENERATE->List.of("首尾帧","尾帧","过渡");case REFERENCE_GENERATE->List.of("多模态","参考图","参考视频");case STORYBOARD_GUIDED->List.of("分镜","故事板");case VIDEO_EDIT,AUDIO_EDIT->List.of("编辑","修改");case EXTEND_FORWARD,EXTEND_BACKWARD->List.of("延长","续写");case WHITE_MODEL_RENDER->List.of("白模","3D");case GENERATE->List.of("生成","视频");});List<Integer> order=new ArrayList<>();for(int i=0;i<blocks.length;i++)order.add(i);order.sort(Comparator.<Integer>comparingInt(i->score(blocks[i],keywords)).reversed().thenComparingInt(i->i));Set<Integer> selected=new HashSet<>();int used=0;for(int index:order){String block=blocks[index].trim();if(block.isBlank())continue;if(used+block.length()+2>maxChars)continue;selected.add(index);used+=block.length()+2;}StringBuilder out=new StringBuilder();for(int i=0;i<blocks.length;i++)if(selected.contains(i)){if(out.length()>0)out.append("\n\n");out.append(blocks[i].trim());}if(out.isEmpty())return paragraphPrefix(markdown,maxChars);return out.toString();}
 private int score(String block,List<String>keywords){int score=block.startsWith("# ")?100:0;for(String keyword:keywords)if(block.contains(keyword))score+=5;return score+Math.min(20,block.length()/500);}
 private String paragraphPrefix(String value,int max){int boundary=value.lastIndexOf("\n\n",Math.min(max,value.length()));return value.substring(0,boundary>0?boundary:Math.min(max,value.length())).trim();}
}
